import random

def generate(rng: random.Random, kind: str) -> str:
    if kind == "edge":
        # 최솟값(N=M=1) 또는 최댓값(N=M=8) 중 하나를 랜덤 선택
        if rng.random() < 0.5:
            N, M = 1, 1
        else:
            N, M = 8, 8
    elif kind == "stress":
        # 제약조건 최댓값 근처: N은 6~8, M은 N에 가까운 값
        N = rng.randint(6, 8)
        M = rng.randint(max(1, N - 1), N)
    else:  # general
        N = rng.randint(1, 8)
        M = rng.randint(1, N)

    return f"{N} {M}\n"
